<script setup lang="ts">
import type { Animal, MedicineProduct, Paginated, TreatmentCourse } from '~/types/api'
const { request } = useApi(); const animals = ref<Animal[]>([]); const products = ref<MedicineProduct[]>([]); const submitting = ref(false); const errorMessage = ref('')
const form = reactive({ animal: '', product: '', reason: '', dosage: '', route: '', started_on: new Date().toISOString().slice(0, 10), planned_doses: 1, frequency_hours: null as number | null, notes: '' })
onMounted(async () => { const [a, p] = await Promise.all([request<Paginated<Animal>>('/animals/?status=active'), request<Paginated<MedicineProduct>>('/medicine/products/')]); animals.value = a.results; products.value = p.results })
async function submit() { submitting.value = true; errorMessage.value = ''; try { const course = await request<TreatmentCourse>('/medicine/courses/', { method: 'POST', body: form }); await navigateTo(`/medicine/courses/${course.id}`) } catch { errorMessage.value = 'The treatment course could not be started.' } finally { submitting.value = false } }
</script>
<template><section class="form-card wide"><p class="eyebrow">Clinical treatment</p><h1>Start treatment course</h1><form class="form-grid" @submit.prevent="submit"><label>Animal <select v-model="form.animal" required><option value="">Select animal</option><option v-for="item in animals" :key="item.id" :value="item.id">{{ item.ear_tag }} · {{ item.name || item.species }}</option></select></label><label>Medicine <select v-model="form.product" required><option value="">Select product</option><option v-for="item in products" :key="item.id" :value="item.id">{{ item.name }} {{ item.concentration }}</option></select></label><label>Reason <input v-model="form.reason" required></label><label>Prescribed dosage <input v-model="form.dosage" placeholder="e.g. 2 ml" required></label><label>Route <input v-model="form.route" placeholder="e.g. subcutaneous"></label><label>Start date <input v-model="form.started_on" type="date" required></label><label>Planned doses <input v-model.number="form.planned_doses" type="number" min="1" required></label><label>Frequency (hours) <input v-model.number="form.frequency_hours" type="number" min="1"></label><label class="full">Notes <textarea v-model="form.notes" rows="4" /></label><p v-if="errorMessage" class="error full">{{ errorMessage }}</p><div class="actions full"><NuxtLink to="/medicine">Cancel</NuxtLink><button :disabled="submitting">{{ submitting ? 'Starting…' : 'Start course' }}</button></div></form></section></template>
